// Package engine runs automation flows. It decides when steps run and in
// what order; every action step is a thin adapter over code that already
// exists elsewhere, registered here through the node contract.
package engine

import (
	"context"
	"fmt"
	"sort"
	"sync"
	"time"

	"github.com/no-dal/ndl-ce/internal/automation/expr"
	"github.com/no-dal/ndl-ce/internal/automation/flowdef"
)

// Categories group node types in the step picker.
const (
	CategoryLogic  = "logic"
	CategoryAction = "action"
	CategoryNodal  = "ndl"
)

// Field is one editor control, generated by the UI from the catalogue.
// Type is text, textarea, number, boolean, select, json, expression,
// duration, connection, target, cases, rules or headers.
type Field struct {
	Key         string   `json:"key"`
	Label       string   `json:"label"`
	Type        string   `json:"type"`
	Required    bool     `json:"required,omitempty"`
	Help        string   `json:"help,omitempty"`
	Placeholder string   `json:"placeholder,omitempty"`
	Default     any      `json:"default,omitempty"`
	Options     []Option `json:"options,omitempty"`
	// Target is the kind of thing a target field picks (workload,
	// container, monitor, pool, script, backup_policy, project, channel).
	Target string `json:"target,omitempty"`
}

// Option is one choice of a select field.
type Option struct {
	Value string `json:"value"`
	Label string `json:"label"`
}

// ExecInput is what a node sees when it runs.
type ExecInput struct {
	ClusterID string
	FlowID    string
	RunID     string
	NodeID    string
	Scope     string
	ActorID   string
	DryRun    bool
	// Config is the node's config with {{ }} references rendered.
	Config map[string]any
	// Env is the data expressions read (trigger, nodes, vars, inputs, run,
	// item, index).
	Env    map[string]any
	Item   any
	Index  int
	Now    time.Time
	Limits flowdef.Limits
	// Connection opens a saved connection's secret fields.
	Connection func(id string) (map[string]any, error)
	logf       func(level, msg string)
}

// Log writes one redacted run log line.
func (in *ExecInput) Log(level, format string, args ...any) {
	if in.logf != nil {
		in.logf(level, fmt.Sprintf(format, args...))
	}
}

// Eval evaluates an expression-valued config field.
func (in *ExecInput) Eval(src string) (any, error) {
	return expr.Eval(flowdef.StripBraces(src), in.Env)
}

// String reads a config value as text.
func (in *ExecInput) String(key string) string {
	v, ok := in.Config[key]
	if !ok || v == nil {
		return ""
	}
	return expr.Stringify(v)
}

// Bool reads a config value as true/false.
func (in *ExecInput) Bool(key string) bool {
	switch v := in.Config[key].(type) {
	case bool:
		return v
	case string:
		return v == "true"
	}
	return false
}

// Int reads a config value as a whole number.
func (in *ExecInput) Int(key string, def int) int {
	switch v := expr.Normalize(in.Config[key]).(type) {
	case float64:
		return int(v)
	case string:
		var n int
		if _, err := fmt.Sscanf(v, "%d", &n); err == nil {
			return n
		}
	}
	return def
}

// RuleResult is how one rule of a condition evaluated (test runs show it).
type RuleResult struct {
	Rule    string `json:"rule"`
	Left    any    `json:"left,omitempty"`
	Op      string `json:"op,omitempty"`
	Right   any    `json:"right,omitempty"`
	Matched bool   `json:"matched"`
}

// Result is what a node returns.
type Result struct {
	Output any
	Vars   map[string]any
	// Port is the branch taken (condition, switch, approval).
	Port string
	// WaitUntil parks the run until then (delay).
	WaitUntil time.Time
	// WaitApproval parks the run until a person approves or rejects.
	WaitApproval bool
	// Stop ends the run, as succeeded unless StopFailed.
	Stop       bool
	StopFailed bool
	Message    string
	Rules      []RuleResult
	// Would is a dry run's sentence: what the step would have done.
	Would string
}

// Preview is a dry run's description of an action that was not run.
type Preview struct {
	Would    string
	Problems []string
	Target   string
}

// NodeType is the contract every step implements. The engine never
// switches on type names; adding a step means calling Register.
type NodeType struct {
	Type        string   `json:"type"`
	DisplayName string   `json:"display_name"`
	Description string   `json:"description"`
	Category    string   `json:"category"`
	Branches    []string `json:"branches,omitempty"`
	Fields      []Field  `json:"fields"`
	// Idempotent steps may be retried after a failure.
	Idempotent bool `json:"idempotent"`
	// Destructive steps count against the per-target limit and require a
	// successful test run before publishing.
	Destructive bool `json:"destructive"`
	// Action steps never run during a test run; Preview describes them.
	Action bool `json:"action"`
	Loop   bool `json:"loop,omitempty"`
	// Expressions are config keys read as expressions, not templates.
	Expressions  []string `json:"-"`
	SetsVariable string   `json:"-"`

	Execute func(ctx context.Context, in *ExecInput) (Result, error)  `json:"-"`
	Preview func(ctx context.Context, in *ExecInput) (Preview, error) `json:"-"`
	// TargetOf names what a destructive step acts on, for the ledger.
	TargetOf func(in *ExecInput) string `json:"-"`
}

// Registry holds the node types.
type Registry struct {
	mu    sync.RWMutex
	types map[string]NodeType
}

// NewRegistry returns a registry with the built-in logic and HTTP steps.
func NewRegistry(deps BuiltinDeps) *Registry {
	r := &Registry{types: map[string]NodeType{}}
	registerBuiltins(r, deps)
	return r
}

// Register adds or replaces a node type.
func (r *Registry) Register(t NodeType) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.types[t.Type] = t
}

// Get finds a node type.
func (r *Registry) Get(typ string) (NodeType, bool) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	t, ok := r.types[typ]
	return t, ok
}

// NodeSpec implements flowdef.Catalog.
func (r *Registry) NodeSpec(typ string) (flowdef.NodeSpec, bool) {
	t, ok := r.Get(typ)
	if !ok {
		return flowdef.NodeSpec{}, false
	}
	spec := flowdef.NodeSpec{Branches: t.Branches, Loop: t.Loop, SetsVariable: t.SetsVariable, Expressions: t.Expressions}
	for _, f := range t.Fields {
		if f.Required {
			spec.Required = append(spec.Required, f.Key)
		}
	}
	return spec, true
}

// Catalogue lists every node type for the UI, ordered by category.
func (r *Registry) Catalogue() []NodeType {
	r.mu.RLock()
	defer r.mu.RUnlock()
	out := make([]NodeType, 0, len(r.types))
	for _, t := range r.types {
		out = append(out, t)
	}
	order := map[string]int{CategoryLogic: 0, CategoryAction: 1, CategoryNodal: 2}
	sort.Slice(out, func(i, j int) bool {
		if order[out[i].Category] != order[out[j].Category] {
			return order[out[i].Category] < order[out[j].Category]
		}
		return out[i].DisplayName < out[j].DisplayName
	})
	return out
}

// HasDestructive reports whether a definition contains a destructive step.
func (r *Registry) HasDestructive(d *flowdef.Definition) []string {
	var out []string
	for _, n := range d.Nodes {
		if t, ok := r.Get(n.Type); ok && t.Destructive {
			out = append(out, n.ID)
		}
	}
	return out
}
